using System;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "TricksterCrossStaffOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/TricksterCrossStaffOmenData")]
public class TricksterCrossStaffOmenData : OnRerollOmenData
{
	protected override Action<List<DiceInstance>> InitializeOmenAction(OmenInstance omenInstance)
	{
		return delegate(List<DiceInstance> diceInstances)
		{
			for (int i = 0; i < diceInstances.Count; i++)
			{
				if (diceInstances[i].DiceOwnerEnum == DiceOwnerEnum.ENEMY)
				{
					omenInstance.EnqueueOmenFeedbackAndPlay();
					ActivateOmen(diceInstances[i].ActionOwner);
				}
			}
		};
	}

	public override string OmenConvertedDescription()
	{
		return GetOmenRawLocalizedDescription() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + base.OmenConvertedDescription();
	}
}
